import{_ as t,o,c as a,a3 as d}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Capture Backends","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Capture Backends | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/design/capture-backends"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/capture-backends"}]]},"headers":[],"relativePath":"catter/design/capture-backends.md","filePath":"en/catter/design/capture-backends.md","lastUpdated":1793109318000}'),r={name:"catter/design/capture-backends.md"};function n(s,e,i,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="capture-backends" tabindex="-1">Capture Backends <a class="header-anchor" href="#capture-backends" aria-label="Permalink to &quot;Capture Backends&quot;">​</a></h1><p>A capture backend is how catter gets a build&#39;s commands: it starts the build, and reports each command the build starts to catter, which has the session&#39;s handlers decide it and tells them how it ended. The handlers see the same commands, decisions and events whichever backend reports them.</p><h2 id="choosing-one" tabindex="-1">Choosing one <a class="header-anchor" href="#choosing-one" aria-label="Permalink to &quot;Choosing one&quot;">​</a></h2><p><code>--capture &lt;backend&gt;</code> names the backend that captures the build: <code>hook</code>, the default, or <code>wrapper</code>. <code>--from &lt;file&gt;</code> replays a recorded build instead of running one: a recorded build is not captured, so <code>--from</code> takes no <code>--capture</code>, and a name no backend has is an error too. Both are reported before anything runs.</p><p>A handler learns the backend from the session&#39;s <code>initialize</code> message, whose <code>mode</code> is its name, or <code>replay</code> for a recorded build.</p><h2 id="what-a-backend-does" tabindex="-1">What a backend does <a class="header-anchor" href="#what-a-backend-does" aria-label="Permalink to &quot;What a backend does&quot;">​</a></h2><ul><li><strong>It starts the build</strong>, and catter ends as the build did. catter stands in for the build command: a SIGTERM, SIGINT or SIGHUP sent to catter goes on to it, and the build command ends when catter is killed.</li><li><strong>It reports each command before it runs</strong>: its working directory, program, arguments and environment, and the command that started it. The commands of a parallel build come at once. A command catter could not capture comes as an <code>error</code> instead.</li><li><strong>It runs each command as the handlers decide</strong>: as it is (<code>skip</code>), changed (<code>modify</code>, <code>edit</code>), or not at all (<code>drop</code>, which ends it with exit code 0). Once a handler aborts the build or fails, the command and every command the build starts after it end with exit code 1 without running.</li><li><strong>It reports how each command ended</strong>, before any command the build starts once that command has ended, and before the build&#39;s own end.</li></ul><h2 id="backends" tabindex="-1">Backends <a class="header-anchor" href="#backends" aria-label="Permalink to &quot;Backends&quot;">​</a></h2><h3 id="hook-default" tabindex="-1">hook (default) <a class="header-anchor" href="#hook-default" aria-label="Permalink to &quot;hook (default)&quot;">​</a></h3><ul><li><strong>How it works</strong>: a hook library is loaded into every process of the build and intercepts process creation (the <code>execve</code> / <code>posix_spawn</code> family on Linux and macOS, <code>CreateProcess</code> on Windows). On Linux and macOS each command then runs through <code>catter-proxy</code>, which asks catter and runs the command as decided, with the hook; on Windows the hook asks catter itself, and starts the program as catter decides. See <a href="./hook-mechanism">Hook mechanism</a> and <a href="./ipc-protocol">IPC protocol</a>.</li><li><strong>Platforms</strong>: Linux, macOS, Windows.</li><li><strong>What it sees</strong>: every process of the build, each with the command that started it, but for what a program the hook cannot be loaded into starts: the program is reported and runs as decided, without the hook. On macOS those are Apple&#39;s own tools (<code>/bin/sh</code>, <code>/usr/bin/make</code>), which run as arm64e and from which System Integrity Protection drops the hook, and Intel programs under Rosetta; on Windows, 32-bit (x86) programs. A program a Windows program starts under another account is not seen at all.</li><li>The build and its commands run on catter&#39;s own stdin, stdout and stderr: they write straight to the terminal, with their colors and in the order they write.</li></ul><h3 id="replay-from" tabindex="-1">replay (<code>--from</code>) <a class="header-anchor" href="#replay-from" aria-label="Permalink to &quot;replay (`--from`)&quot;">​</a></h3><ul><li><strong>How it works</strong>: it plays the build a file recorded instead of running one: each command, error and exit in the file&#39;s order, with the IDs and parent commands the file gives them. The build ends with the exit code the file records.</li><li><strong>Actions</strong>: nothing runs, so <code>skip</code>, <code>drop</code>, <code>modify</code> and <code>edit</code> change nothing. <code>abort</code> ends the replay as it ends a live build: no later event reaches the handlers, and catter exits 1.</li></ul><h3 id="wrapper" tabindex="-1">wrapper <a class="header-anchor" href="#wrapper" aria-label="Permalink to &quot;wrapper&quot;">​</a></h3><ul><li><strong>How it works</strong>: before each directory on the build&#39;s <code>PATH</code>, catter puts one of the session&#39;s own, with a shim of each compiler, linker and archiver it knows by its name there: whichever names a build tool looks for, and in whichever order, it finds the program it would without catter, through its shim. A variable such as <code>CC</code>, <code>CXX</code> or <code>AR</code> that names a program by its path names that program&#39;s shim instead, and CMake runs every compile and link through the wrapper backend&#39;s launcher (<code>CMAKE_&lt;LANG&gt;_COMPILER_LAUNCHER</code> and <code>CMAKE_&lt;LANG&gt;_LINKER_LAUNCHER</code>); on Windows MSBuild runs <code>cl.exe</code>, <code>link.exe</code> and <code>lib.exe</code> from the shims (<code>CLToolPath</code>, <code>LinkToolPath</code> and <code>LibToolPath</code>), each unless the build sets it. A shim is <code>catter-proxy</code>: it reports its command, runs the program it stands in for as decided, and reports how it ended. The program it runs finds no shims on its <code>PATH</code>: a compiler a build cache runs, as ccache runs the one past its own directory, is the compiler, not the shim again.</li><li><strong>Platforms</strong>: Linux, macOS, Windows.</li><li><strong>What it sees</strong>: the programs it has shims of, whatever in the build runs them, Apple&#39;s <code>/usr/bin/make</code> and <code>/bin/sh</code> included. A command&#39;s parent is the nearest program with a shim that started it, or the build command; what a compiler starts is not seen.</li><li><strong>Limitations</strong>: a build that runs a compiler by the path it found before catter ran, as the <code>build.ninja</code> CMake wrote does, escapes the shims: configure it and build it in one session, <code>catter compile-commands --capture wrapper -- sh -c &quot;cmake -B build &amp;&amp; cmake --build build&quot;</code>. The shims go with the session, so a build configured under the wrapper backend runs only in that session: configure one for catter of its own. A program the build puts first on <code>PATH</code> itself, as a toolchain&#39;s directory, is found before the shims, and one found through a relative entry of <code>PATH</code>, which names another directory wherever the build goes, has no shim. On Windows only <code>.exe</code> programs have shims, and a project that sets <code>CLToolPath</code>, <code>LinkToolPath</code> or <code>LibToolPath</code> itself, as a toolset other than MSVC&#39;s may, runs those tools past them.</li></ul><h2 id="capability-matrix" tabindex="-1">Capability matrix <a class="header-anchor" href="#capability-matrix" aria-label="Permalink to &quot;Capability matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Backend</th><th>Platforms</th><th>How it captures</th><th>Actions</th><th>Parent command</th><th>Status</th></tr></thead><tbody><tr><td>hook</td><td>Linux / macOS / Windows</td><td>a hook in every process of the build</td><td><code>skip</code> <code>drop</code> <code>abort</code> <code>modify</code> <code>edit</code></td><td>the process that started it</td><td>implemented (default)</td></tr><tr><td>replay</td><td>any</td><td>a recorded build (<code>--from</code>)</td><td>only <code>abort</code> takes effect</td><td>as recorded</td><td>implemented</td></tr><tr><td>wrapper</td><td>Linux / macOS / Windows</td><td>compiler shims on <code>PATH</code>, <code>CC</code> / <code>CXX</code></td><td><code>skip</code> <code>drop</code> <code>abort</code> <code>modify</code> <code>edit</code></td><td>the nearest wrapped program</td><td>implemented</td></tr></tbody></table><h2 id="writing-handlers-for-any-backend" tabindex="-1">Writing handlers for any backend <a class="header-anchor" href="#writing-handlers-for-any-backend" aria-label="Permalink to &quot;Writing handlers for any backend&quot;">​</a></h2><ul><li>Do not assume one: <code>initialize</code> names it (<code>mode</code>).</li><li>A command&#39;s parent is the command that started it as far as the backend sees: features that rely on the process tree (command trees, target trees) should not assume every process in between is there.</li></ul>',18)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
